import std.io

pub type AppError = Failed(String)

record CountIter { n: Int64 }

impl Iterator<Int64> for CountIter {
    fn next(mut self) -> Option<Int64> {
        return None
    }
}

record Range2 { n: Int64 }

impl Iterable<Int64> for Range2 {
    type Iter = CountIter
    fn iterator(self) -> CountIter {
        return CountIter { n: 0 }
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let r = Range2 { n: 0 }
    for c in r {
        io.println("${c}")
    }
    return Ok(())
}
